#!/usr/bin/env python3
# @orchestrator: Magnús Smárason | smarason.is  @created: 2026-08-15
"""V-28: a generated file must say so, and name what generates it.

WHY THIS EXISTS
---------------
A correction made by editing a generated file such as deposit/README.md, which
is written by ingest/build_deposit.py, is silently reverted by the next build:
it lasts exactly until the next run and then disappears without any check
noticing.

This is a standing failure mode in this project rather than a one-off: removing a
symptom instead of its source, and being surprised when it comes back. schema.sql
and figure_provenance.json both already carry a header saying they are generated.
README.md, data_dictionary.json and results_traceability.md did not, and the one
I edited was one of those.

WHAT IT ASSERTS
---------------
Every artefact known to be written by a generator carries, near the top, a line
saying it is generated and naming the script that writes it. Nothing more: it
cannot verify the content is current — V-25 does that for Source Data — only that
a person opening the file is told not to edit it.

That is a weak property deliberately. The strong version is regenerating each
artefact and diffing, which needs every generator to be callable without side
effects. This is the cheap guard that would have stopped the actual mistake.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).parent.parent

# artefact -> the generator that writes it
GENERATED = {
    "deposit/README.md": "ingest/build_deposit.py",
    "deposit/schema.sql": "ingest/build_deposit.py",
    "deposit/data_dictionary.json": "ingest/build_deposit.py",
    # The writer moved. build_traceability_table.py writes the CSV and
    # render_traceability_md.py renders the Markdown from it - its own
    # comment records why ("One artefact, one writer: when this file also
    # wrote the Markdown, the CSV was corrected and the published table
    # kept saying PENDING for three claims that had been answered"). This
    # mapping was not updated with it, so the gate asked the artefact to
    # name a generator that no longer writes it. Found 6 October 2026.
    "deposit/results_traceability.md": "ingest/render_traceability_md.py",
    # MANIFEST.sha256.json is deliberately absent: it is a checksum map
    # consumed by V-14 and by readers' own tooling, and injecting prose
    # into it to satisfy this gate would damage the artefact to please
    # the check. Declared here rather than silently omitted.
    # figure_provenance.json is NOT generated. Nothing writes it; it is
    # hand-maintained, and the binding evidence in it is checked by V-23
    # instead.
    "schema.sql": "pg_dump via make schema",
}

DECLARES = re.compile(r"generated|do not edit|autogenerated|auto-generated", re.I)
HEAD_LINES = 12


def main() -> int:
    missing: list[str] = []
    unnamed: list[str] = []
    absent: list[str] = []
    examined = 0

    for rel, generator in sorted(GENERATED.items()):
        p = ROOT / rel
        if not p.exists():
            absent.append(f"{rel} (written by {generator}) is not present")
            continue
        examined += 1
        head = "\n".join(p.read_text(errors="ignore").splitlines()[:HEAD_LINES])
        if not DECLARES.search(head):
            missing.append(f"{rel}: no line in the first {HEAD_LINES} says it is generated")
            continue
        # Naming the generator is the part that saves the next person a grep.
        stem = Path(generator).name.split()[0]
        if stem not in head:
            unnamed.append(f"{rel}: says it is generated but does not name {stem}")

    print(f"V-28 generated headers: EXAMINED {examined} of {len(GENERATED)} artefact(s)")
    for a in absent:
        print(f"  NOT PRESENT: {a}")

    problems = missing + unnamed
    if problems:
        print(f"\nV-28 FAIL: {len(problems)} artefact(s) do not warn a reader:\n")
        for m in problems:
            print(f"  {m}")
        print("\nEditing a generated file is work that disappears at the next build.")
        print("It happened on 2026-08-15 to deposit/README.md and was caught by")
        print("accident. The header is the cheap guard; fix the generator, not the")
        print("artefact.")
        return 1

    if examined == 0:
        print("V-28 FAIL: no artefact was examined, so this would pass for free.")
        return 1

    print(f"\nV-28 PASS: every generated artefact present says so and names its "
          f"generator. This does not establish that any of them is up to date.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
